using System;
using System.Net;
using Microsoft.Extensions.Logging;

namespace X3Code.Utils.HTTP;

/// <summary>
/// The log events the HTTP client writes. Generated by the LoggerMessage source generator, so a
/// call costs nothing while the level is switched off.
/// </summary>
/// <remarks>
/// Everything goes through <see cref="ILogger"/>, the abstraction. This library brings no sink and
/// no configuration; where the events end up is entirely the consuming application's decision.
/// </remarks>
internal static partial class HttpClientLog
{
    [LoggerMessage(EventId = 2000, Level = LogLevel.Warning,
        Message = "HTTP request to {Uri} answered {StatusCode}. Response body: {ResponseContent}")]
    internal static partial void RequestFailed(ILogger logger, string? uri, HttpStatusCode statusCode, string? responseContent);

    [LoggerMessage(EventId = 2001, Level = LogLevel.Debug,
        Message = "Could not read the response body of the failed request to {Uri}.")]
    internal static partial void ResponseBodyUnreadable(ILogger logger, string? uri, Exception exception);
}
